const rawBody = $input.first().json.body || $input.first().json;
const body = rawBody.body || rawBody;

const required = ['source', 'chapter'];
const missing = required.filter(field => body[field] === undefined || body[field] === null);

if (missing.length > 0) {
  return {
    json: {
      valid: false,
      error: {
        code: 400,
        message: `Missing required parameters: ${missing.join(', ')}`,
        status: 'BAD_REQUEST'
      }
    }
  };
}

if (typeof body.chapter !== 'number' || body.chapter < 1) {
  return {
    json: {
      valid: false,
      error: {
        code: 400,
        message: 'chapter must be a positive integer',
        status: 'BAD_REQUEST'
      }
    }
  };
}

return {
  json: {
    valid: true,
    source: body.source,
    chapter: body.chapter,
    language: body.language || 'fr',
    force: body.force || false,
    anthropic_api_key: body.anthropic_api_key,
    model: body.model || 'claude-3-5-sonnet-20241022',
    discord_user_id: body.discord_user_id || body.user_id
  }
};

const validData = $('Validate Input').first().json;
const chapterData = $input.first().json;

if (!chapterData.segments || chapterData.segments.length === 0) {
  return {
    json: {
      error: true,
      message: 'No segments found'
    }
  };
}

// Filter segments that need translation
const toTranslate = validData.force 
  ? chapterData.segments 
  : chapterData.segments.filter(s => !s.text_translated && !s.translation);

if (toTranslate.length === 0) {
  return {
    json: {
      already_translated: true,
      source: validData.source,
      chapter: validData.chapter,
      segments: chapterData.segments
    }
  };
}

return {
  json: {
    already_translated: false,
    source: validData.source,
    chapter: validData.chapter,
    title: chapterData.title,
    to_translate: toTranslate,
    all_segments: chapterData.segments,
    language: validData.language,
    anthropic_api_key: validData.anthropic_api_key,
    model: validData.model,
    discord_user_id: validData.discord_user_id
  }
};

const filterData = $('Filter Untranslated Segments').first().json;
const llmResponse = $input.first().json;

try {
  if (llmResponse.error) {
    throw new Error(llmResponse.error.message || 'Claude API error');
  }

  const content = llmResponse.content?.[0]?.text || '';
  let jsonStr = content;
  const jsonMatch = content.match(/```json\n?([\s\S]*?)\n?```/);
  if (jsonMatch) {
    jsonStr = jsonMatch[1];
  }

  const parsed = JSON.parse(jsonStr);
  const translationsMap = {};
  parsed.translations.forEach(t => {
    translationsMap[t.index] = t.translation;
  });

  // Merge translations with all segments
  const mergedSegments = filterData.all_segments.map(s => ({
    index: s.index,
    text: s.text_hebrew || s.text,
    translation: translationsMap[s.index] || s.text_translated || s.translation || null
  }));

  return {
    json: {
      success: true,
      source: filterData.source,
      chapter: filterData.chapter,
      title: filterData.title,
      segments: mergedSegments,
      translated_count: parsed.translations.length,
      language: filterData.language,
      discord_user_id: filterData.discord_user_id
    }
  };
} catch (e) {
  return {
    json: {
      success: false,
      error: e.message,
      source: filterData.source,
      chapter: filterData.chapter
    }
  };
}
